func {name}(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		// CORS lets a browser page served from ONE origin read answers from another. The answer below names the page's origin — TODO: replace it with the one origin your own page is served from
		w.Header().Set("Access-Control-Allow-Origin", "TODO: https://your-page.example")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS")
		w.Header().Set("Access-Control-Allow-Headers", "Content-Type, Authorization")
		// Never answer "*" for the origin when requests carry cookies or tokens — a wildcard plus credentials is the combination browsers reject and attackers love; an origin must be named
		if r.Method == http.MethodOptions {
			// The browser's preflight question, asked before the real request: the headers above are the whole answer
			w.WriteHeader(http.StatusNoContent)
			return
		}
		next(w, r)
	}
}

func {name}(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		secret := os.Getenv("JWT_SECRET")
		// TODO: JWT_SECRET is the environment variable your server reads its signing secret from — the same one the token was created with. This code never obeys the token's own "alg" header: it always checks with HMAC-SHA256, so a token asking for a weaker (or "none") check gets nothing
		token, found := strings.CutPrefix(r.Header.Get("Authorization"), "Bearer ")
		parts := strings.Split(token, ".")
		verified := false
		var claims map[string]any
		if found && len(parts) == 3 {
			unsigned := parts[0] + "." + parts[1]
			mac := hmac.New(sha256.New, []byte(secret))
			mac.Write([]byte(unsigned))
			signature, sigErr := base64.RawURLEncoding.DecodeString(parts[2])
			if sigErr == nil && hmac.Equal(signature, mac.Sum(nil)) {
				payload, payloadErr := base64.RawURLEncoding.DecodeString(parts[1])
				if payloadErr == nil && json.Unmarshal(payload, &claims) == nil {
					if exp, isNumber := claims["exp"].(float64); isNumber && time.Now().Unix() < int64(exp) {
						verified = true
					}
				}
			}
		}
		if !verified {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		// TODO: claims now holds claims you can trust — claims["sub"] says who the token was issued to. Pass that on (a request context is the usual way) instead of believing anything the request itself claims about who sent it
		_ = claims
		next(w, r)
	}
}

type {name}Key struct{}

// {name} mints a fresh nonce — a one-time random value — for every request, sets the Content-Security-Policy header that demands it, and passes the value along for the page's own templates.
func {name}(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		raw := make([]byte, 16)
		if _, err := rand.Read(raw); err != nil {
			// No honest randomness, no honest nonce — refuse rather than send a page whose policy a stranger could guess
			http.Error(w, "internal error", http.StatusInternalServerError)
			return
		}
		nonce := base64.StdEncoding.EncodeToString(raw)
		w.Header().Set("Content-Security-Policy", "default-src 'self'; script-src 'self' 'nonce-"+nonce+"'; style-src 'self' 'nonce-"+nonce+"'")
		// TODO: your templates read this request's nonce back with r.Context().Value({name}Key{}) and write it onto their own tags — <script nonce="..."> — because a script WITHOUT this request's nonce is exactly what the browser now refuses to run
		next(w, r.WithContext(context.WithValue(r.Context(), {name}Key{}, nonce)))
	}
}

func {name}(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		// CSRF: a malicious page can make a signed-in browser SEND your server a request, but it can never READ your pages — so a state-changing request must hand back a random token only a page you served could know (the double-submit pattern)
		cookie, cookieErr := r.Cookie("csrf_token")
		token := ""
		if cookieErr == nil {
			token = cookie.Value
		}
		if token == "" {
			raw := make([]byte, 32)
			if _, err := rand.Read(raw); err != nil {
				http.Error(w, "internal error", http.StatusInternalServerError)
				return
			}
			token = base64.StdEncoding.EncodeToString(raw)
			http.SetCookie(w, &http.Cookie{Name: "csrf_token", Value: token, Path: "/", HttpOnly: true, SameSite: http.SameSiteLaxMode})
			// A fresh token was just minted for the NEXT request — this one still has nothing proven, and the check below refuses it if it tries to change anything
		}
		if r.Method != http.MethodGet && r.Method != http.MethodHead && r.Method != http.MethodOptions {
			sent := r.Header.Get("X-CSRF-Token")
			if sent == "" {
				sent = r.FormValue("csrf_token")
			}
			if subtle.ConstantTimeCompare([]byte(sent), []byte(token)) != 1 {
				http.Error(w, "forbidden", http.StatusForbidden)
				return
			}
