}

// {name} counts requests per visitor inside a fixed window; past the limit the answer is 429 until the window turns over.
var {name}State = struct {
	sync.Mutex
	windowStart time.Time
	counts      map[string]int
}{windowStart: time.Now(), counts: map[string]int{}}

func {name}(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		visitor, _, splitErr := net.SplitHostPort(r.RemoteAddr)
		if splitErr != nil {
			visitor = r.RemoteAddr
		}
		{name}State.Lock()
		if time.Since({name}State.windowStart) >= time.Minute {
			// TODO: your window — one minute here. A window turning over wipes every count at once
			{name}State.windowStart = time.Now()
			{name}State.counts = map[string]int{}
		}
		{name}State.counts[visitor]++
		count := {name}State.counts[visitor]
		{name}State.Unlock()
		if count > 100 {
			// TODO: your limit — requests per window, per visitor
			http.Error(w, "too many requests", http.StatusTooManyRequests)
			return
		}
		next(w, r)
	}
}

